(window.QBANK=window.QBANK||{}).english={"threads":[{"id":"eng_words","subject":"english","subject_he":"אנגלית","name":"אוצר מילים ואותיות","emoji":"🔤","nodes":[{"g0":3,"grade":4,"tag":"Pre-A1","label":"אוצר מילים ואותיות","topics":["ENG-PreA1-VOCAB","ENG-PreA1-LITERACY"],"topics_he":["ENG-PreA1-VOCAB","ENG-PreA1-LITERACY"]},{"g0":4,"grade":6,"tag":"A1","label":"אוצר מילים ואותיות","topics":["ENG-A1-VOCAB"],"topics_he":["ENG-A1-VOCAB"]},{"g0":7,"grade":9,"tag":"A2","label":"אוצר מילים ואותיות","topics":["ENG-A2-VOCAB"],"topics_he":["ENG-A2-VOCAB"]},{"g0":10,"grade":12,"tag":"B1","label":"אוצר מילים ואותיות","topics":["ENG-A2plus-VOCAB","ENG-B1-VOCAB","ENG-B2-VOCAB"],"topics_he":["ENG-A2plus-VOCAB","ENG-B1-VOCAB","ENG-B2-VOCAB"]}]},{"id":"eng_reading","subject":"english","subject_he":"אנגלית","name":"דקדוק והבנת הנקרא","emoji":"🇬🇧","nodes":[{"g0":3,"grade":4,"tag":"Pre-A1","label":"דקדוק והבנת הנקרא","topics":["ENG-PreA1-RECEPTION-WRITTEN","ENG-PreA1-LITERACY"],"topics_he":["ENG-PreA1-RECEPTION-WRITTEN","ENG-PreA1-LITERACY"]},{"g0":4,"grade":6,"tag":"A1","label":"דקדוק והבנת הנקרא","topics":["ENG-A1-GRAMMAR","ENG-A1-RECEPTION-WRITTEN"],"topics_he":["ENG-A1-GRAMMAR","ENG-A1-RECEPTION-WRITTEN"]},{"g0":7,"grade":9,"tag":"A2","label":"דקדוק והבנת הנקרא","topics":["ENG-A2-GRAMMAR","ENG-A2-RECEPTION-WRITTEN"],"topics_he":["ENG-A2-GRAMMAR","ENG-A2-RECEPTION-WRITTEN"]},{"g0":10,"grade":12,"tag":"B1","label":"דקדוק והבנת הנקרא","topics":["ENG-A2plus-GRAMMAR","ENG-B1-GRAMMAR","ENG-B2-GRAMMAR","ENG-B1-RECEPTION-WRITTEN","ENG-B2-RECEPTION-WRITTEN"],"topics_he":["ENG-A2plus-GRAMMAR","ENG-B1-GRAMMAR","ENG-B2-GRAMMAR","ENG-B1-RECEPTION-WRITTEN","ENG-B2-RECEPTION-WRITTEN"]}]}],"questions":[{"question_id":"Q-ENG-A1-GRAMMAR-L1-010","topic_id":"ENG-A1-GRAMMAR","level":1,"qtype":"mc","stem":"השלימו: She ___ a student","answer":"b","options":[{"key":"a","text":"am","diagnosis":"agreement error — 'am' goes only with 'I'"},{"key":"b","text":"is","diagnosis":"correct"},{"key":"c","text":"be","diagnosis":"unconjugated base form — 'be' paradigm not acquired"},{"key":"d","text":"are","diagnosis":"subject-verb agreement error — form of 'be' not matched to 'she'"}],"solution":"With he/she/it we use 'is': She is a student.","skill":"Present simple of 'be' — subject agreement","misconceptions":["be-agreement"],"area":"E-STR","area_he":"מבנה המשפט ו-to be","tier":"core"},{"question_id":"Q-ENG-A1-GRAMMAR-L1-011","topic_id":"ENG-A1-GRAMMAR","level":1,"qtype":"mc","stem":"השלימו: One cat, two ___","answer":"c","options":[{"key":"a","text":"cat's","diagnosis":"apostrophe confusion — possessive form used for plural"},{"key":"b","text":"cat","diagnosis":"plural -s omitted — final -s is often dropped by Hebrew speakers"},{"key":"c","text":"cats","diagnosis":"correct"},{"key":"d","text":"cates","diagnosis":"overgeneralized spelling of the plural ending"}],"solution":"The plural of cat is cats: two cats.","skill":"Regular plural -s","misconceptions":["plural-s-omission","apostrophe-plural"],"area":"E-STR","area_he":"מבנה המשפט ו-to be","tier":"core"},{"question_id":"Q-ENG-A1-GRAMMAR-L2-010","topic_id":"ENG-A1-GRAMMAR","level":2,"qtype":"mc","stem":"מה התשובה הנכונה לשאלה How old are you?","answer":"b","options":[{"key":"a","text":"I ten years old.","diagnosis":"missing 'am' — Hebrew has no present-tense 'be', so the copula is dropped"},{"key":"b","text":"I am ten years old.","diagnosis":"correct"},{"key":"c","text":"I have ten years old.","diagnosis":"blend of the L1 'have' pattern and the English chunk"},{"key":"d","text":"I have ten years.","diagnosis":"L1 interference: Hebrew/Romance pattern 'yesh li / I have X years' instead of 'be X years old'"}],"solution":"In English age is expressed with 'be': I am ten years old.","skill":"Expressing age with 'be' (not 'have')","misconceptions":["have-for-age","zero-copula"],"area":"E-STR","area_he":"מבנה המשפט ו-to be","tier":"core"},{"question_id":"Q-ENG-A1-GRAMMAR-L2-011","topic_id":"ENG-A1-GRAMMAR","level":2,"qtype":"mc","stem":"השלימו: Dan ___ to school every day","answer":"c","options":[{"key":"a","text":"gos","diagnosis":"spelling of the -es ending after o not acquired"},{"key":"b","text":"go","diagnosis":"third-person -s omitted — the most common A1 form error"},{"key":"c","text":"goes","diagnosis":"correct"},{"key":"d","text":"going","diagnosis":"-ing form without auxiliary — progressive/simple confusion (Hebrew has one present tense)"}],"solution":"With he/she/it in present simple we add -(e)s: Dan goes.","skill":"Present simple third-person -s","misconceptions":["third-person-s-omission","one-present-tense-L1"],"area":"E-GRA","area_he":"זמנים ודקדוק","tier":"core"},{"question_id":"Q-ENG-A1-GRAMMAR-L2-012","topic_id":"ENG-A1-GRAMMAR","level":2,"qtype":"mc","stem":"השלימו: What does your father do? He is ___ teacher","answer":"d","options":[{"key":"a","text":"(no word)","diagnosis":"article omission — Hebrew has no indefinite article ('aba sheli more'), classic L1 interference"},{"key":"b","text":"an","diagnosis":"a/an rule applied without checking the first sound of the next word"},{"key":"c","text":"the","diagnosis":"definite/indefinite confusion — 'the' used as an all-purpose article"},{"key":"d","text":"a","diagnosis":"correct"}],"solution":"Before a profession we use a/an: He is a teacher.","skill":"Indefinite article a/an with professions","misconceptions":["article-omission-hebrew"],"area":"E-STR","area_he":"מבנה המשפט ו-to be","tier":"core"},{"question_id":"Q-ENG-A1-GRAMMAR-L3-010","topic_id":"ENG-A1-GRAMMAR","level":3,"qtype":"mc","stem":"השלימו: ___ you like ice cream?","answer":"b","options":[{"key":"a","text":"Does","diagnosis":"do/does agreement error with 'you'"},{"key":"b","text":"Do","diagnosis":"correct"},{"key":"c","text":"Is","diagnosis":"'be' overgeneralization + agreement error"},{"key":"d","text":"Are","diagnosis":"'be' overgeneralized to all questions — do-support not acquired"}],"solution":"Questions in present simple use do/does: Do you like ice cream?","skill":"Yes/no questions with do-support","misconceptions":["missing-do-support","be-overgeneralization"],"area":"E-GRA","area_he":"זמנים ודקדוק","tier":"core"},{"question_id":"Q-ENG-A1-GRAMMAR-L3-011","topic_id":"ENG-A1-GRAMMAR","level":3,"qtype":"mc","stem":"השלימו: I ___ like fish","answer":"c","options":[{"key":"a","text":"doesn't","diagnosis":"do/does agreement error with 'I'"},{"key":"b","text":"no","diagnosis":"'I no like' — negation with bare 'no', direct transfer from L1 negation patterns"},{"key":"c","text":"don't","diagnosis":"correct"},{"key":"d","text":"am not","diagnosis":"'be' negation overgeneralized to a lexical verb"}],"solution":"Negative present simple uses don't/doesn't: I don't like fish.","skill":"Negation with do-support","misconceptions":["missing-do-support","bare-no-negation"],"area":"E-GRA","area_he":"זמנים ודקדוק","tier":"core"},{"question_id":"Q-ENG-A1-RECEPTION-WRITTEN-L1-010","topic_id":"ENG-A1-RECEPTION-WRITTEN","level":1,"qtype":"mc","stem":"לפי הקטע Dan has a dog. The dog is black — מה צבע הכלב?","answer":"b","options":[{"key":"a","text":"white","diagnosis":"guessed without locating the answer in the text"},{"key":"b","text":"black","diagnosis":"correct"},{"key":"c","text":"Dan","diagnosis":"picked a word from the text without understanding the question word 'color'"},{"key":"d","text":"brown","diagnosis":"guessed a typical dog color instead of reading the text"}],"solution":"The text says: The dog is black.","skill":"Picking out concrete information from a very short text","misconceptions":["guessing-not-reading","question-word-comprehension"],"area":"E-REA","area_he":"הבנת הנקרא","tier":"core"},{"question_id":"Q-ENG-A1-RECEPTION-WRITTEN-L1-011","topic_id":"ENG-A1-RECEPTION-WRITTEN","level":1,"qtype":"mc","stem":"לפי הקטע Maya is seven. She likes cats — בת כמה מאיה?","answer":"c","options":[{"key":"a","text":"She likes cats.","diagnosis":"answered with the wrong sentence — question word 'how old' not understood"},{"key":"b","text":"eight","diagnosis":"number read carelessly or guessed"},{"key":"c","text":"seven","diagnosis":"correct"},{"key":"d","text":"three","diagnosis":"guessed — answer not located in the text"}],"solution":"The text says: Maya is seven.","skill":"Understanding 'How old...?' and finding the answer in a short text","misconceptions":["question-word-comprehension"],"area":"E-REA","area_he":"הבנת הנקרא","tier":"core"},{"question_id":"Q-ENG-A1-RECEPTION-WRITTEN-L2-010","topic_id":"ENG-A1-RECEPTION-WRITTEN","level":2,"qtype":"mc","stem":"בספרייה יש שלט Please be quiet — מה צריך לעשות שם?","answer":"b","options":[{"key":"a","text":"Read fast.","diagnosis":"associated a library idea instead of reading the sign"},{"key":"b","text":"Be quiet.","diagnosis":"correct"},{"key":"c","text":"Go home.","diagnosis":"guessed — sign not decoded"},{"key":"d","text":"Talk to friends.","diagnosis":"opposite of the instruction — 'quiet' not understood"}],"solution":"The sign asks people to be quiet.","skill":"Understanding routine notices and simple instructions","misconceptions":["association-over-meaning"],"area":"E-REA","area_he":"הבנת הנקרא","tier":"core"},{"question_id":"Q-ENG-A1-RECEPTION-WRITTEN-L2-011","topic_id":"ENG-A1-RECEPTION-WRITTEN","level":2,"qtype":"mc","stem":"לפי הפתק של טום Mom, I am at Ben's house. I will come home at six — איפה טום?","answer":"c","options":[{"key":"a","text":"at six","diagnosis":"time/place confusion — question word 'where' not understood"},{"key":"b","text":"at home","diagnosis":"took 'home' from the second sentence — that is where he will be later, not now"},{"key":"c","text":"at Ben's house","diagnosis":"correct"},{"key":"d","text":"at his school","diagnosis":"guessed a typical place — answer not located in the note"}],"solution":"The note says: I am at Ben's house.","skill":"Scanning a short message for concrete information (where)","misconceptions":["question-word-comprehension","wrong-sentence-scan"],"area":"E-REA","area_he":"הבנת הנקרא","tier":"core"},{"question_id":"Q-ENG-A1-RECEPTION-WRITTEN-L2-012","topic_id":"ENG-A1-RECEPTION-WRITTEN","level":2,"qtype":"mc","stem":"לפי ההזמנה Come to my party on Sunday at four o'clock at my house — מתי המסיבה?","answer":"d","options":[{"key":"a","text":"at my house","diagnosis":"place given instead of time — when/where confusion"},{"key":"b","text":"on Monday at four o'clock","diagnosis":"day read carelessly"},{"key":"c","text":"on Sunday at six o'clock","diagnosis":"time read carelessly — partial scanning"},{"key":"d","text":"on Sunday at four o'clock","diagnosis":"correct"}],"solution":"The invitation says: on Sunday at four o'clock.","skill":"Finding time information in a short everyday text","misconceptions":["question-word-comprehension","careless-scanning"],"area":"E-REA","area_he":"הבנת הנקרא","tier":"core"},{"question_id":"Q-ENG-A1-RECEPTION-WRITTEN-L3-010","topic_id":"ENG-A1-RECEPTION-WRITTEN","level":3,"qtype":"mc","stem":"לפי הקטע Lily has two brothers. They play football in the park every Friday. Lily watches them — מה האחים עושים בכל יום שישי?","answer":"b","options":[{"key":"a","text":"They play in school.","diagnosis":"place detail changed — careless reading of 'in the park'"},{"key":"b","text":"They play football.","diagnosis":"correct"},{"key":"c","text":"They watch TV.","diagnosis":"guessed from the word 'watches' without tracking who watches whom"},{"key":"d","text":"They watch Lily.","diagnosis":"pronoun reference error — 'they' and 'them' mixed up"}],"solution":"'They' = the brothers; they play football in the park. Lily watches them.","skill":"Tracking pronoun reference across sentences","misconceptions":["pronoun-reference"],"area":"E-REA","area_he":"הבנת הנקרא","tier":"core"},{"question_id":"Q-ENG-A1-RECEPTION-WRITTEN-L3-011","topic_id":"ENG-A1-RECEPTION-WRITTEN","level":3,"qtype":"mc","stem":"לפי הקטע Sam gets up at seven. He eats breakfast and goes to school by bus. After school he does his homework — איך סם מגיע לבית הספר?","answer":"c","options":[{"key":"a","text":"he walks","diagnosis":"guessed — answer not located in the text"},{"key":"b","text":"at seven","diagnosis":"scanned the wrong detail — 'how' answered with a time"},{"key":"c","text":"by bus","diagnosis":"correct"},{"key":"d","text":"by car","diagnosis":"guessed a typical answer instead of locating it in the text"}],"solution":"The text says: ...goes to school by bus.","skill":"Scanning a three-sentence text for a specific detail (how)","misconceptions":["question-word-comprehension","careless-scanning"],"area":"E-REA","area_he":"הבנת הנקרא","tier":"core"},{"question_id":"Q-ENG-A1-VOCAB-L1-010","topic_id":"ENG-A1-VOCAB","level":1,"qtype":"mc","stem":"איזו מילה היא פרי?","answer":"b","options":[{"key":"a","text":"potato","diagnosis":"fruit/vegetable category confusion"},{"key":"b","text":"apple","diagnosis":"correct"},{"key":"c","text":"juice","diagnosis":"association with fruit (fruit juice) but not a fruit itself"},{"key":"d","text":"bread","diagnosis":"food-category overgeneralization — food but not fruit"}],"solution":"An apple is a fruit; bread, potato and juice are not fruits.","skill":"Sorting Band I words into meaning categories","misconceptions":["category-overgeneralization"],"area":"E-VOC","area_he":"אוצר מילים","tier":"core"},{"question_id":"Q-ENG-A1-VOCAB-L1-011","topic_id":"ENG-A1-VOCAB","level":1,"qtype":"mc","stem":"השלימו: The elephant is big, but the mouse is ___","answer":"c","options":[{"key":"a","text":"slow","diagnosis":"association with animals, not the opposite of big"},{"key":"b","text":"short","diagnosis":"size-adjective confusion — short is about height/length, not general size"},{"key":"c","text":"small","diagnosis":"correct"},{"key":"d","text":"old","diagnosis":"familiar adjective, wrong meaning — opposite pair not retrieved"}],"solution":"The opposite of big is small.","skill":"Using basic opposite adjectives in a sentence","misconceptions":["opposite-pairs"],"area":"E-VOC","area_he":"אוצר מילים","tier":"core"},{"question_id":"Q-ENG-A1-VOCAB-L2-010","topic_id":"ENG-A1-VOCAB","level":2,"qtype":"mc","stem":"השלימו: My mother's mother is my ___","answer":"b","options":[{"key":"a","text":"sister","diagnosis":"family relations not mapped — chose a familiar family word"},{"key":"b","text":"grandmother","diagnosis":"correct"},{"key":"c","text":"grandfather","diagnosis":"right generation, wrong gender — kinship terms not separated by gender"},{"key":"d","text":"aunt","diagnosis":"family-word confusion — aunt is the mother's sister"}],"solution":"Your mother's mother is your grandmother.","skill":"Family vocabulary and relations","misconceptions":["family-terms","kinship-gender"],"area":"E-VOC","area_he":"אוצר מילים","tier":"core"},{"question_id":"Q-ENG-A1-VOCAB-L2-011","topic_id":"ENG-A1-VOCAB","level":2,"qtype":"mc","stem":"איזה יום בא אחרי Monday?","answer":"c","options":[{"key":"a","text":"Saturday","diagnosis":"days known but sequence not stable"},{"key":"b","text":"Sunday","diagnosis":"gave the day BEFORE Monday — after/before confusion"},{"key":"c","text":"Tuesday","diagnosis":"correct"},{"key":"d","text":"Thursday","diagnosis":"Tuesday/Thursday confusion — similar-sounding day names"}],"solution":"Sunday, Monday, Tuesday — Tuesday comes after Monday.","skill":"Days of the week in order","misconceptions":["tuesday-thursday-confusion"],"area":"E-VOC","area_he":"אוצר מילים","tier":"core"},{"question_id":"Q-ENG-A1-VOCAB-L2-012","topic_id":"ENG-A1-VOCAB","level":2,"qtype":"mc","stem":"השלימו: You write with a ___","answer":"d","options":[{"key":"a","text":"paper","diagnosis":"associated classroom word — but you write ON paper, not WITH it"},{"key":"b","text":"chair","diagnosis":"classroom word chosen without meaning check"},{"key":"c","text":"book","diagnosis":"associated with school but not a writing tool"},{"key":"d","text":"pencil","diagnosis":"correct"}],"solution":"You write with a pencil (or a pen).","skill":"Classroom-object vocabulary in context","misconceptions":["association-over-meaning"],"area":"E-VOC","area_he":"אוצר מילים","tier":"core"},{"question_id":"Q-ENG-A1-VOCAB-L3-010","topic_id":"ENG-A1-VOCAB","level":3,"qtype":"mc","stem":"השלימו: You wear shoes on your ___","answer":"b","options":[{"key":"a","text":"hands","diagnosis":"body-part confusion — meaning not retrieved"},{"key":"b","text":"feet","diagnosis":"correct"},{"key":"c","text":"legs","diagnosis":"near-meaning body part — Hebrew 'regel' covers both leg and foot, classic L1 interference"},{"key":"d","text":"foots","diagnosis":"regular-plural overgeneralization — irregular plural 'feet' not acquired"}],"solution":"Shoes go on your feet (irregular plural of foot).","skill":"Body-part vocabulary and irregular plurals","misconceptions":["plural-overgeneralization","hebrew-regel-leg-foot"],"area":"E-VOC","area_he":"אוצר מילים","tier":"core"},{"question_id":"Q-ENG-A1-VOCAB-L3-011","topic_id":"ENG-A1-VOCAB","level":3,"qtype":"mc","stem":"השלימו: I am thirsty. I want to ___ some water","answer":"c","options":[{"key":"a","text":"make","diagnosis":"general verb used instead of the specific one — limited verb range"},{"key":"b","text":"eat","diagnosis":"eat/drink collocation confusion"},{"key":"c","text":"drink","diagnosis":"correct"},{"key":"d","text":"wash","diagnosis":"association with water but wrong meaning for 'thirsty'"}],"solution":"When you are thirsty, you drink water.","skill":"Choosing the correct verb for the context (thirsty → drink)","misconceptions":["verb-collocation"],"area":"E-VOC","area_he":"אוצר מילים","tier":"core"},{"question_id":"Q-ENG-A2-GRAMMAR-L1-010","topic_id":"ENG-A2-GRAMMAR","level":1,"qtype":"mc","stem":"Choose the correct answer: Yesterday I ___ to the beach with my friends.","answer":"c","options":[{"key":"a","text":"was go","diagnosis":"'be' inserted as a past marker — auxiliary system not sorted"},{"key":"b","text":"go","diagnosis":"unmarked present form — past tense not produced despite 'yesterday'"},{"key":"c","text":"went","diagnosis":"correct"},{"key":"d","text":"goed","diagnosis":"regular-past overgeneralization to an irregular verb"}],"solution":"go is irregular: go → went. Yesterday I went to the beach.","skill":"Past simple of irregular verbs","misconceptions":["past-overgeneralization","be-as-tense-marker"],"area":"E-GRA","area_he":"זמנים ודקדוק","tier":"core"},{"question_id":"Q-ENG-A2-GRAMMAR-L1-011","topic_id":"ENG-A2-GRAMMAR","level":1,"qtype":"mc","stem":"Choose the correct answer: Shh! Look! The baby ___ now.","answer":"d","options":[{"key":"a","text":"sleeps","diagnosis":"present simple used for an action happening now — Hebrew has one present tense, classic interference"},{"key":"b","text":"sleeping","diagnosis":"auxiliary 'is' dropped — progressive form incomplete"},{"key":"c","text":"sleep","diagnosis":"bare form — neither tense marked"},{"key":"d","text":"is sleeping","diagnosis":"correct"}],"solution":"For actions happening now we use present progressive: The baby is sleeping.","skill":"Present progressive for actions happening now","misconceptions":["one-present-tense-L1","aux-omission"],"area":"E-GRA","area_he":"זמנים ודקדוק","tier":"core"},{"question_id":"Q-ENG-A2-GRAMMAR-L2-010","topic_id":"ENG-A2-GRAMMAR","level":2,"qtype":"mc","stem":"Choose the correct answer: My brother is ___ than me.","answer":"c","options":[{"key":"a","text":"the tallest","diagnosis":"superlative/comparative confusion"},{"key":"b","text":"tall","diagnosis":"comparative unmarked — 'than' signal ignored"},{"key":"c","text":"taller","diagnosis":"correct"},{"key":"d","text":"more tall","diagnosis":"'more' overgeneralized to a short adjective"}],"solution":"Short adjectives take -er: taller than me.","skill":"Comparative adjectives with -er","misconceptions":["more-overgeneralization","comparative-superlative-confusion"],"area":"E-GRA","area_he":"זמנים ודקדוק","tier":"core"},{"question_id":"Q-ENG-A2-GRAMMAR-L2-011","topic_id":"ENG-A2-GRAMMAR","level":2,"qtype":"mc","stem":"___ you watch the game last night?","answer":"d","options":[{"key":"a","text":"Do","diagnosis":"past question without tense marking — 'last night' ignored"},{"key":"b","text":"Were","diagnosis":"'be' overgeneralized to a lexical-verb question"},{"key":"c","text":"Was","diagnosis":"'be' overgeneralization + agreement error"},{"key":"d","text":"Did","diagnosis":"correct"}],"solution":"Past simple questions use did: Did you watch the game?","skill":"Past simple questions with did","misconceptions":["missing-do-support","be-overgeneralization"],"area":"E-GRA","area_he":"זמנים ודקדוק","tier":"core"},{"question_id":"Q-ENG-A2-GRAMMAR-L2-012","topic_id":"ENG-A2-GRAMMAR","level":2,"qtype":"mc","stem":"Choose the correct answer: Tomorrow we ___ visit our grandmother.","answer":"a","options":[{"key":"a","text":"are going to","diagnosis":"correct"},{"key":"b","text":"are going","diagnosis":"'to' dropped — structure incomplete"},{"key":"c","text":"will going to","diagnosis":"two future forms blended — 'will' mixed with 'be going to'"},{"key":"d","text":"going to","diagnosis":"auxiliary 'are' dropped — 'be going to' structure incomplete (Hebrew zero copula)"}],"solution":"Future plans: be going to + verb — We are going to visit our grandmother.","skill":"Future with 'be going to'","misconceptions":["aux-omission","zero-copula","future-form-blend"],"area":"E-GRA","area_he":"זמנים ודקדוק","tier":"core"},{"question_id":"Q-ENG-A2-GRAMMAR-L3-010","topic_id":"ENG-A2-GRAMMAR","level":3,"qtype":"mc","stem":"Choose the correct answer: She ___ to the party last week.","answer":"c","options":[{"key":"a","text":"not went","diagnosis":"bare 'not' negation — do-support missing, L1-style negation"},{"key":"b","text":"didn't went","diagnosis":"double past marking — tense marked on both auxiliary and main verb, very common error"},{"key":"c","text":"didn't go","diagnosis":"correct"},{"key":"d","text":"doesn't went","diagnosis":"tense on the wrong element + double marking"}],"solution":"After didn't the verb returns to base form: didn't go.","skill":"Past simple negative — base form after didn't","misconceptions":["double-tense-marking","missing-do-support"],"area":"E-GRA","area_he":"זמנים ודקדוק","tier":"core"},{"question_id":"Q-ENG-A2-GRAMMAR-L3-011","topic_id":"ENG-A2-GRAMMAR","level":3,"qtype":"mc","stem":"Choose the correct answer: Eilat is ___ city in Israel.","answer":"d","options":[{"key":"a","text":"the most hot","diagnosis":"'most' overgeneralized to a short adjective"},{"key":"b","text":"hotter","diagnosis":"comparative/superlative confusion — comparing one against all needs superlative"},{"key":"c","text":"hottest","diagnosis":"article 'the' dropped from the superlative — Hebrew pattern without article"},{"key":"d","text":"the hottest","diagnosis":"correct"}],"solution":"Superlative of short adjectives: the + -est → the hottest city.","skill":"Superlative adjectives with 'the ... -est'","misconceptions":["most-overgeneralization","superlative-article-omission"],"area":"E-GRA","area_he":"זמנים ודקדוק","tier":"core"},{"question_id":"Q-ENG-A2-RECEPTION-WRITTEN-L1-010","topic_id":"ENG-A2-RECEPTION-WRITTEN","level":1,"qtype":"mc","stem":"Read: 'Ben's class went on a trip to the Galilee. They walked near a river and ate lunch under the trees. Everyone was tired but happy.' Where did the class eat lunch?","answer":"c","options":[{"key":"a","text":"on the bus","diagnosis":"guessed from the trip context — answer not located"},{"key":"b","text":"near a river","diagnosis":"took the place of walking, not of eating — matched the wrong verb"},{"key":"c","text":"under the trees","diagnosis":"correct"},{"key":"d","text":"in a restaurant","diagnosis":"guessed a typical lunch place — answer not located"}],"solution":"They ate lunch under the trees (walking was near the river).","skill":"Locating a specific detail in a short factual text","misconceptions":["wrong-detail-match"],"area":"E-REA","area_he":"הבנת הנקרא","tier":"core"},{"question_id":"Q-ENG-A2-RECEPTION-WRITTEN-L1-011","topic_id":"ENG-A2-RECEPTION-WRITTEN","level":1,"qtype":"mc","stem":"Advertisement: 'New! Pizza Roma — open every day from 12:00 to 23:00. Children eat free on Mondays!' When do children eat free?","answer":"d","options":[{"key":"a","text":"every day","diagnosis":"took the general opening hours instead of the special condition"},{"key":"b","text":"at 12:00","diagnosis":"scanned a time instead of the day — wrong detail"},{"key":"c","text":"on weekends","diagnosis":"guessed — condition not located in the text"},{"key":"d","text":"on Mondays","diagnosis":"correct"}],"solution":"The ad says: Children eat free on Mondays.","skill":"Scanning an everyday text for a specific condition","misconceptions":["overgeneralizing-conditions"],"area":"E-REA","area_he":"הבנת הנקרא","tier":"core"},{"question_id":"Q-ENG-A2-RECEPTION-WRITTEN-L2-010","topic_id":"ENG-A2-RECEPTION-WRITTEN","level":2,"qtype":"mc","stem":"Read: 'Dogs need a lot of care. You must walk them every day and give them good food. A dog can be a wonderful friend, but only if you look after it well.' What is the main idea of the text?","answer":"c","options":[{"key":"a","text":"Cats are better than dogs.","diagnosis":"not in the text at all — answered from personal opinion"},{"key":"b","text":"Dogs eat a lot of food.","diagnosis":"picked a detail instead of the main idea"},{"key":"c","text":"Taking care of a dog is important.","diagnosis":"correct"},{"key":"d","text":"Walking is good exercise for people.","diagnosis":"shifted the topic — 'walk them' misread as being about people"}],"solution":"All three sentences are about caring for a dog properly.","skill":"Identifying the main idea of a short factual text","misconceptions":["detail-as-main-idea","opinion-over-text"],"area":"E-REA","area_he":"הבנת הנקרא","tier":"core"},{"question_id":"Q-ENG-A2-RECEPTION-WRITTEN-L2-011","topic_id":"ENG-A2-RECEPTION-WRITTEN","level":2,"qtype":"mc","stem":"Notice: 'The school library is open on Sunday, Tuesday and Thursday from 8:00 to 14:00. On Friday it closes at 12:00. Books can be borrowed for two weeks.' How long can you keep a library book?","answer":"d","options":[{"key":"a","text":"until Friday","diagnosis":"matched a salient day from a different sentence"},{"key":"b","text":"from 8:00 to 14:00","diagnosis":"answered 'how long' with opening hours — wrong detail type"},{"key":"c","text":"two days","diagnosis":"careless reading — 'weeks' misread as 'days'"},{"key":"d","text":"two weeks","diagnosis":"correct"}],"solution":"The notice says: Books can be borrowed for two weeks.","skill":"Scanning a notice with several details for the right one","misconceptions":["wrong-detail-match","careless-scanning"],"area":"E-REA","area_he":"הבנת הנקרא","tier":"core"},{"question_id":"Q-ENG-A2-RECEPTION-WRITTEN-L2-012","topic_id":"ENG-A2-RECEPTION-WRITTEN","level":2,"qtype":"mc","stem":"Sara wrote to her friend: 'I can't come to your party on Saturday. My family is driving to Haifa to visit my uncle, who is in hospital. I hope we can meet next week.' Why can't Sara come to the party?","answer":"a","options":[{"key":"a","text":"Her family is going to visit her uncle.","diagnosis":"correct"},{"key":"b","text":"The party is in Haifa.","diagnosis":"combined details incorrectly — Haifa is where the family is driving"},{"key":"c","text":"She doesn't like big parties.","diagnosis":"invented a reason that is not in the text"},{"key":"d","text":"She is in hospital in Haifa.","diagnosis":"referent confusion — the uncle, not Sara, is in hospital"}],"solution":"Sara's family is driving to Haifa to visit her uncle in hospital, so she can't come.","skill":"Understanding reasons and who-did-what in a personal message","misconceptions":["referent-confusion","detail-recombination"],"area":"E-REA","area_he":"הבנת הנקרא","tier":"core"},{"question_id":"Q-ENG-A2-RECEPTION-WRITTEN-L3-010","topic_id":"ENG-A2-RECEPTION-WRITTEN","level":3,"qtype":"mc","stem":"Read: 'Omer started judo lessons a year ago. At first it was hard, and he wanted to stop. His coach told him to keep trying. Now Omer has a green belt and loves every lesson.' How did Omer feel about judo at first?","answer":"c","options":[{"key":"a","text":"He wanted to teach judo.","diagnosis":"misread 'his coach told him' — roles confused"},{"key":"b","text":"He loved it from the first lesson.","diagnosis":"took the ending ('loves every lesson') and ignored the time phrase 'at first'"},{"key":"c","text":"He found it difficult.","diagnosis":"correct"},{"key":"d","text":"He was the best in the class.","diagnosis":"invented from the green-belt detail — inference beyond the text"}],"solution":"'At first it was hard, and he wanted to stop' — he found it difficult.","skill":"Tracking a change over time in a narrative text","misconceptions":["time-phrase-ignored","role-confusion"],"area":"E-REA","area_he":"הבנת הנקרא","tier":"core"},{"question_id":"Q-ENG-A2-RECEPTION-WRITTEN-L3-011","topic_id":"ENG-A2-RECEPTION-WRITTEN","level":3,"qtype":"mc","stem":"Read: 'Omer started judo lessons a year ago. At first it was hard, and he wanted to stop. His coach told him to keep trying. Now Omer has a green belt and loves every lesson.' What is the best title for this text?","answer":"d","options":[{"key":"a","text":"Getting a Green Belt","diagnosis":"too narrow — turns one detail into the whole message"},{"key":"b","text":"A Famous Judo Coach","diagnosis":"minor character promoted to topic — main character misidentified"},{"key":"c","text":"Sports in Israel","diagnosis":"too general — title does not match the specific story"},{"key":"d","text":"Don't Give Up","diagnosis":"correct"}],"solution":"The story's message is persistence: Omer almost stopped, kept trying, and succeeded.","skill":"Choosing a title that captures the message of a text","misconceptions":["title-too-narrow","title-too-general"],"area":"E-REA","area_he":"הבנת הנקרא","tier":"core"},{"question_id":"Q-ENG-A2-VOCAB-L1-010","topic_id":"ENG-A2-VOCAB","level":1,"qtype":"mc","stem":"This phone is very expensive. I don't have enough money to ___ it.","answer":"c","options":[{"key":"a","text":"spend","diagnosis":"spend/buy confusion — you spend money, you buy things"},{"key":"b","text":"sell","diagnosis":"buy/sell direction confusion"},{"key":"c","text":"buy","diagnosis":"correct"},{"key":"d","text":"pay","diagnosis":"collocation error — you pay FOR something, you don't 'pay it'"}],"solution":"You buy things; you pay for things; you spend money.","skill":"Shopping verbs and their objects (buy/sell/pay/spend)","misconceptions":["verb-collocation"],"area":"E-VOC","area_he":"אוצר מילים","tier":"core"},{"question_id":"Q-ENG-A2-VOCAB-L1-011","topic_id":"ENG-A2-VOCAB","level":1,"qtype":"mc","stem":"I was very tired, so I went to bed ___.","answer":"d","options":[{"key":"a","text":"late","diagnosis":"early/late opposite confusion — logic of 'so' not applied"},{"key":"b","text":"fast","diagnosis":"near-meaning adverb that does not fit the context"},{"key":"c","text":"hardly","diagnosis":"hard/hardly false friend inside English — meaning not known"},{"key":"d","text":"early","diagnosis":"correct"}],"solution":"Tired → go to bed early. 'So' shows a logical result.","skill":"Adverbs of time in a logical context","misconceptions":["opposite-pairs","connector-logic"],"area":"E-VOC","area_he":"אוצר מילים","tier":"core"},{"question_id":"Q-ENG-A2-VOCAB-L2-010","topic_id":"ENG-A2-VOCAB","level":2,"qtype":"mc","stem":"The film was really funny — everyone ___ a lot.","answer":"c","options":[{"key":"a","text":"smiled","diagnosis":"close meaning but does not collocate with 'a lot' for a funny film — weaker fit than 'laughed'"},{"key":"b","text":"cried","diagnosis":"emotion-verb confusion — opposite reaction"},{"key":"c","text":"laughed","diagnosis":"correct"},{"key":"d","text":"shouted","diagnosis":"near-meaning 'loud reaction' verb — precise meaning not known"}],"solution":"funny → laugh: everyone laughed a lot.","skill":"Emotion/reaction verbs and their meaning","misconceptions":["near-synonym-confusion"],"area":"E-VOC","area_he":"אוצר מילים","tier":"core"},{"question_id":"Q-ENG-A2-VOCAB-L2-011","topic_id":"ENG-A2-VOCAB","level":2,"qtype":"mc","stem":"Can I ___ your pen for a minute, please?","answer":"d","options":[{"key":"a","text":"lend","diagnosis":"borrow/lend direction confusion — Hebrew 'lish'ol/lehash'il' pair maps badly onto English; the receiver borrows"},{"key":"b","text":"take","diagnosis":"general verb used instead of the precise one — politeness meaning of 'borrow' missed"},{"key":"c","text":"bring","diagnosis":"bring/take/borrow confusion — transfer verbs not differentiated"},{"key":"d","text":"borrow","diagnosis":"correct"}],"solution":"The person who receives borrows; the owner lends: Can I borrow your pen?","skill":"borrow vs. lend (direction of transfer)","misconceptions":["borrow-lend-direction"],"area":"E-VOC","area_he":"אוצר מילים","tier":"core"},{"question_id":"Q-ENG-A2-VOCAB-L2-012","topic_id":"ENG-A2-VOCAB","level":2,"qtype":"mc","stem":"I have to ___ my homework before dinner.","answer":"a","options":[{"key":"a","text":"do","diagnosis":"correct"},{"key":"b","text":"write","diagnosis":"too-narrow verb — possible but not the fixed collocation tested"},{"key":"c","text":"work","diagnosis":"word-family confusion — 'work' used as the verb for homework"},{"key":"d","text":"make","diagnosis":"make/do confusion — Hebrew 'la'asot' covers both; homework takes 'do'"}],"solution":"The collocation is 'do homework' (not 'make homework').","skill":"make vs. do collocations","misconceptions":["make-do-confusion"],"area":"E-VOC","area_he":"אוצר מילים","tier":"core"},{"question_id":"Q-ENG-A2-VOCAB-L3-010","topic_id":"ENG-A2-VOCAB","level":3,"qtype":"mc","stem":"It's dark in here. Please ___ the light.","answer":"c","options":[{"key":"a","text":"put","diagnosis":"incomplete phrasal verb — particle missing"},{"key":"b","text":"open","diagnosis":"direct translation of Hebrew 'liftoach et ha'or' — classic L1 interference"},{"key":"c","text":"turn on","diagnosis":"correct"},{"key":"d","text":"close","diagnosis":"open/close frame transferred from Hebrew AND direction reversed"}],"solution":"In English lights are turned on/off, not opened/closed.","skill":"turn on/off vs. open/close (L1 interference collocation)","misconceptions":["open-the-light-interference"],"area":"E-VOC","area_he":"אוצר מילים","tier":"core"},{"question_id":"Q-ENG-A2-VOCAB-L3-011","topic_id":"ENG-A2-VOCAB","level":3,"qtype":"mc","stem":"Ron didn't win, but he was happy to take ___ in the race.","answer":"d","options":[{"key":"a","text":"place","diagnosis":"blended with the collocation 'take place' (= happen)"},{"key":"b","text":"care","diagnosis":"blended with 'take care' — collocations mixed"},{"key":"c","text":"time","diagnosis":"blended with 'take time' — collocation retrieved by frequency, not meaning"},{"key":"d","text":"part","diagnosis":"correct"}],"solution":"take part in = participate: he was happy to take part in the race.","skill":"Fixed collocations with 'take'","misconceptions":["collocation-blending"],"area":"E-VOC","area_he":"אוצר מילים","tier":"core"},{"question_id":"Q-ENG-A2plus-GRAMMAR-L1-010","topic_id":"ENG-A2plus-GRAMMAR","level":1,"qtype":"mc","stem":"He ___ in Tel Aviv for two years when he was a student.","answer":"c","options":[{"key":"a","text":"living","diagnosis":"-ing form without auxiliary — no finite verb"},{"key":"b","text":"lives","diagnosis":"present used for a finished past period — time frame 'when he was a student' ignored"},{"key":"c","text":"lived","diagnosis":"correct"},{"key":"d","text":"was live","diagnosis":"'be' inserted as a tense marker instead of inflecting the verb"}],"solution":"A finished period in the past takes past simple: He lived there for two years.","skill":"Past simple for finished past periods (Band I consolidation)","misconceptions":["tense-time-mismatch","be-as-tense-marker"]},{"question_id":"Q-ENG-A2plus-GRAMMAR-L1-011","topic_id":"ENG-A2plus-GRAMMAR","level":1,"qtype":"mc","stem":"This job is much ___ than my old one.","answer":"d","options":[{"key":"a","text":"more good","diagnosis":"'more' overgeneralized — irregular comparative not retrieved"},{"key":"b","text":"gooder","diagnosis":"-er overgeneralized to an irregular adjective"},{"key":"c","text":"best","diagnosis":"superlative used with 'than' — comparative/superlative confusion"},{"key":"d","text":"better","diagnosis":"correct"}],"solution":"good is irregular: good → better → best. This job is better than my old one.","skill":"Irregular comparatives (Band I-II accuracy)","misconceptions":["comparative-overgeneralization"]},{"question_id":"Q-ENG-A2plus-GRAMMAR-L2-010","topic_id":"ENG-A2plus-GRAMMAR","level":2,"qtype":"mc","stem":"Dana ___ in this restaurant since 2023.","answer":"c","options":[{"key":"a","text":"is working","diagnosis":"progressive without perfect — 'since 2023' requires perfect aspect"},{"key":"b","text":"works","diagnosis":"present simple for a duration up to now — Hebrew uses present here ('ovedet me-az'), classic interference"},{"key":"c","text":"has worked","diagnosis":"correct"},{"key":"d","text":"worked","diagnosis":"past simple cuts the connection to the present — 'since' signal ignored"}],"solution":"since + starting point → present perfect: Dana has worked here since 2023.","skill":"Present perfect with since (receptive/emerging)","misconceptions":["present-for-duration-L1"]},{"question_id":"Q-ENG-A2plus-GRAMMAR-L2-011","topic_id":"ENG-A2plus-GRAMMAR","level":2,"qtype":"mc","stem":"I have never ___ sushi. Is it good?","answer":"d","options":[{"key":"a","text":"ate","diagnosis":"past form instead of past participle after 'have'"},{"key":"b","text":"eat","diagnosis":"base form after 'have' — participle not acquired"},{"key":"c","text":"eating","diagnosis":"-ing after 'have' — perfect and progressive confused"},{"key":"d","text":"eaten","diagnosis":"correct"}],"solution":"have/has + past participle: I have never eaten sushi.","skill":"Present perfect — past participle form","misconceptions":["participle-vs-past"]},{"question_id":"Q-ENG-A2plus-GRAMMAR-L2-012","topic_id":"ENG-A2plus-GRAMMAR","level":2,"qtype":"mc","stem":"If it ___ tomorrow, the trip will be cancelled.","answer":"a","options":[{"key":"a","text":"rains","diagnosis":"correct"},{"key":"b","text":"rain","diagnosis":"third-person -s dropped — agreement error"},{"key":"c","text":"rained","diagnosis":"past in a future condition — conditional types confused"},{"key":"d","text":"will rain","diagnosis":"future in the if-clause — Hebrew uses future in both clauses ('im yered geshem'), classic interference"}],"solution":"First conditional: if + present simple, will in the main clause — If it rains, the trip will be cancelled.","skill":"First conditional — present after if","misconceptions":["future-after-if-L1"]},{"question_id":"Q-ENG-A2plus-GRAMMAR-L3-010","topic_id":"ENG-A2plus-GRAMMAR","level":3,"qtype":"mc","stem":"These phones ___ in China.","answer":"c","options":[{"key":"a","text":"is made","diagnosis":"passive recognized but agreement with plural subject failed"},{"key":"b","text":"make","diagnosis":"active form with a non-agent subject — passive not recognized"},{"key":"c","text":"are made","diagnosis":"correct"},{"key":"d","text":"are making","diagnosis":"progressive instead of passive — 'be + -ing' and 'be + participle' confused"}],"solution":"Passive: be + past participle, agreeing with the subject — These phones are made in China.","skill":"Present simple passive (receptive/emerging)","misconceptions":["active-for-passive","aux-agreement"]},{"question_id":"Q-ENG-A2plus-GRAMMAR-L3-011","topic_id":"ENG-A2plus-GRAMMAR","level":3,"qtype":"mc","stem":"English ___ in many countries around the world.","answer":"d","options":[{"key":"a","text":"speaks","diagnosis":"active form — the subject 'English' cannot be the speaker; passive not recognized"},{"key":"b","text":"is speaking","diagnosis":"progressive instead of passive"},{"key":"c","text":"spoken","diagnosis":"participle without auxiliary — passive structure incomplete"},{"key":"d","text":"is spoken","diagnosis":"correct"}],"solution":"English is spoken = people speak English (passive: be + past participle).","skill":"Recognizing and forming the present passive","misconceptions":["active-for-passive","aux-omission"]},{"question_id":"Q-ENG-A2plus-VOCAB-L1-010","topic_id":"ENG-A2plus-VOCAB","level":1,"qtype":"mc","stem":"I'd like to open a bank ___, please.","answer":"c","options":[{"key":"a","text":"check","diagnosis":"related banking word — collocation 'open an account' not known"},{"key":"b","text":"count","diagnosis":"word-form confusion — count/account not distinguished"},{"key":"c","text":"account","diagnosis":"correct"},{"key":"d","text":"bill","diagnosis":"related money word with the wrong meaning"}],"solution":"The collocation is 'open a bank account'.","skill":"Everyday adult-life collocations (banking)","misconceptions":["word-form-confusion"]},{"question_id":"Q-ENG-A2plus-VOCAB-L1-011","topic_id":"ENG-A2plus-VOCAB","level":1,"qtype":"mc","stem":"The bus was late, so I ___ the beginning of my shift at work.","answer":"d","options":[{"key":"a","text":"lost","diagnosis":"lost/missed confusion — Hebrew 'le'abed/lehachmitz' distinction maps differently; you lose objects, miss events"},{"key":"b","text":"left","diagnosis":"near-form verb with the wrong meaning"},{"key":"c","text":"caught","diagnosis":"opposite meaning — collocation with transport transferred wrongly"},{"key":"d","text":"missed","diagnosis":"correct"}],"solution":"You miss an event or a bus; you lose an object: I missed the beginning of my shift.","skill":"miss vs. lose (L1 interference pair)","misconceptions":["miss-lose-confusion"]},{"question_id":"Q-ENG-A2plus-VOCAB-L2-010","topic_id":"ENG-A2plus-VOCAB","level":2,"qtype":"mc","stem":"Job advertisement: 'We are looking for a waiter with at least one year of ___ in a restaurant.'","answer":"c","options":[{"key":"a","text":"examples","diagnosis":"similar-sounding word — meaning not checked"},{"key":"b","text":"experiments","diagnosis":"experience/experiment word-form confusion"},{"key":"c","text":"experience","diagnosis":"correct"},{"key":"d","text":"exercises","diagnosis":"similar-sounding word — form-based guess"}],"solution":"Work history = experience: one year of experience in a restaurant.","skill":"Work-world vocabulary; distinguishing similar word forms","misconceptions":["word-form-confusion"]},{"question_id":"Q-ENG-A2plus-VOCAB-L2-011","topic_id":"ENG-A2plus-VOCAB","level":2,"qtype":"mc","stem":"The tickets are still cheap, ___ the show is very popular.","answer":"d","options":[{"key":"a","text":"because","diagnosis":"logic reversed — popularity would normally make tickets expensive, so a contrast connector is needed"},{"key":"b","text":"so","diagnosis":"result connector used where contrast is needed"},{"key":"c","text":"and","diagnosis":"neutral connector — contrast relation not recognized"},{"key":"d","text":"even though","diagnosis":"correct"}],"solution":"Cheap tickets + popular show is a surprise, so we need contrast: even though.","skill":"Contrast connectors and text logic","misconceptions":["connector-logic"]},{"question_id":"Q-ENG-A2plus-VOCAB-L2-012","topic_id":"ENG-A2plus-VOCAB","level":2,"qtype":"mc","stem":"My phone battery is almost empty. I need to ___ it.","answer":"a","options":[{"key":"a","text":"charge","diagnosis":"correct"},{"key":"b","text":"pay","diagnosis":"charge/pay money-meaning confusion"},{"key":"c","text":"turn","diagnosis":"incomplete phrasal verb — particle and meaning missing"},{"key":"d","text":"fill","diagnosis":"direct translation of the 'fill up' idea — collocation not known"}],"solution":"Batteries are charged: I need to charge my phone.","skill":"Technology vocabulary in daily-life context","misconceptions":["literal-translation"]},{"question_id":"Q-ENG-A2plus-VOCAB-L3-010","topic_id":"ENG-A2plus-VOCAB","level":3,"qtype":"mc","stem":"The meeting was put ___ until next Monday because the manager was ill.","answer":"c","options":[{"key":"a","text":"out","diagnosis":"particle guessed — 'put out' has a different meaning"},{"key":"b","text":"on","diagnosis":"phrasal-verb particle confusion — 'put on' = wear"},{"key":"c","text":"off","diagnosis":"correct"},{"key":"d","text":"up","diagnosis":"particle guessed by frequency — 'put up' has a different meaning"}],"solution":"put off = postpone: the meeting was put off until Monday.","skill":"Common phrasal verbs (receptive)","misconceptions":["phrasal-verb-particles"]},{"question_id":"Q-ENG-A2plus-VOCAB-L3-011","topic_id":"ENG-A2plus-VOCAB","level":3,"qtype":"mc","stem":"I'm not sure if I'll buy it yet — it depends ___ the price.","answer":"d","options":[{"key":"a","text":"in","diagnosis":"preposition transfer from Hebrew 'taluy b-' — classic L1 interference"},{"key":"b","text":"of","diagnosis":"preposition guessed by frequency — dependent preposition not learned as a unit"},{"key":"c","text":"at","diagnosis":"preposition guessed — verb+preposition unit not acquired"},{"key":"d","text":"on","diagnosis":"correct"}],"solution":"The fixed pattern is 'depend on': it depends on the price.","skill":"Dependent prepositions (depend on)","misconceptions":["preposition-transfer"]},{"question_id":"Q-ENG-B1-GRAMMAR-L1-010","topic_id":"ENG-B1-GRAMMAR","level":1,"qtype":"mc","stem":"We have lived in this house ___ 2015.","answer":"c","options":[{"key":"a","text":"in","diagnosis":"preposition guessed — since/for system not acquired"},{"key":"b","text":"for","diagnosis":"for/since confusion — for takes a length of time, since takes a starting point"},{"key":"c","text":"since","diagnosis":"correct"},{"key":"d","text":"from","diagnosis":"transfer from Hebrew 'mi-2015' — 'from' used instead of 'since' with perfect"}],"solution":"since + starting point (2015); for + length of time (ten years).","skill":"Present perfect with since/for","misconceptions":["for-since-confusion","preposition-transfer"]},{"question_id":"Q-ENG-B1-GRAMMAR-L1-011","topic_id":"ENG-B1-GRAMMAR","level":1,"qtype":"mc","stem":"That's the boy ___ won the chess competition.","answer":"d","options":[{"key":"a","text":"which","diagnosis":"who/which confusion — Hebrew 'she-' covers both people and things, classic interference"},{"key":"b","text":"whom","diagnosis":"object pronoun used for the subject of the clause"},{"key":"c","text":"what","diagnosis":"'what' used as a relative pronoun — non-standard transfer"},{"key":"d","text":"who","diagnosis":"correct"}],"solution":"For people as subject we use who: the boy who won.","skill":"Relative pronouns who/which","misconceptions":["relative-pronoun-transfer"]},{"question_id":"Q-ENG-B1-GRAMMAR-L2-010","topic_id":"ENG-B1-GRAMMAR","level":2,"qtype":"mc","stem":"If you ___ hard, you will pass the test.","answer":"c","options":[{"key":"a","text":"would study","diagnosis":"'would' in the if-clause — conditional structure misplaced"},{"key":"b","text":"will study","diagnosis":"future in the if-clause — Hebrew uses future in both clauses, classic interference"},{"key":"c","text":"study","diagnosis":"correct"},{"key":"d","text":"studied","diagnosis":"second-conditional form in a real condition — conditional types confused"}],"solution":"First conditional: if + present, will + verb — If you study hard, you will pass.","skill":"First conditional","misconceptions":["future-after-if-L1"]},{"question_id":"Q-ENG-B1-GRAMMAR-L2-011","topic_id":"ENG-B1-GRAMMAR","level":2,"qtype":"mc","stem":"Have you finished your homework ___?","answer":"d","options":[{"key":"a","text":"already","diagnosis":"yet/already confusion — already is unusual in neutral questions; yet is the question/negative partner"},{"key":"b","text":"just","diagnosis":"time adverb with the wrong meaning for an open question"},{"key":"c","text":"ever","diagnosis":"'ever' used for a specific current task — experience adverb misapplied"},{"key":"d","text":"yet","diagnosis":"correct"}],"solution":"In questions and negatives about the present period we use yet: Have you finished yet?","skill":"Present perfect adverbs: yet/already/just/ever","misconceptions":["yet-already-confusion"]},{"question_id":"Q-ENG-B1-GRAMMAR-L2-012","topic_id":"ENG-B1-GRAMMAR","level":2,"qtype":"mc","stem":"When I was young, I ___ play outside every day.","answer":"a","options":[{"key":"a","text":"used to","diagnosis":"correct"},{"key":"b","text":"am used to","diagnosis":"'be used to' (= accustomed to) confused with past habit 'used to'"},{"key":"c","text":"was used to","diagnosis":"structures blended — past habit and accustomed-to forms mixed"},{"key":"d","text":"use to","diagnosis":"past marking dropped from 'used to' — form learned from speech"}],"solution":"Past habits: used to + base verb — I used to play outside every day.","skill":"used to for past habits","misconceptions":["used-to-forms"]},{"question_id":"Q-ENG-B1-GRAMMAR-L3-010","topic_id":"ENG-B1-GRAMMAR","level":3,"qtype":"mc","stem":"If I ___ a million dollars, I would travel around the world.","answer":"c","options":[{"key":"a","text":"would have","diagnosis":"'would' moved into the if-clause — result and condition confused"},{"key":"b","text":"have","diagnosis":"present in an unreal condition — second conditional form not acquired"},{"key":"c","text":"had","diagnosis":"correct"},{"key":"d","text":"will have","diagnosis":"future in the if-clause — first/second conditionals blended with L1 future pattern"}],"solution":"Second conditional (unreal): if + past, would + verb — If I had a million dollars, I would travel.","skill":"Second conditional","misconceptions":["conditional-clause-mixing"]},{"question_id":"Q-ENG-B1-GRAMMAR-L3-011","topic_id":"ENG-B1-GRAMMAR","level":3,"qtype":"mc","stem":"If we had more time, we ___ the museum too.","answer":"d","options":[{"key":"a","text":"will visit","diagnosis":"first/second conditional mixing — unreal condition needs would"},{"key":"b","text":"visited","diagnosis":"past copied into the result clause — clause roles confused"},{"key":"c","text":"would have visited","diagnosis":"third-conditional result in a present unreal condition — time frames mixed"},{"key":"d","text":"would visit","diagnosis":"correct"}],"solution":"Second conditional result: would + base verb — we would visit the museum.","skill":"Second conditional — result clause","misconceptions":["conditional-clause-mixing"]},{"question_id":"Q-ENG-B1-RECEPTION-WRITTEN-L1-010","topic_id":"ENG-B1-RECEPTION-WRITTEN","level":1,"qtype":"mc","stem":"Read: 'Every Friday morning, students from a high school in Holon volunteer at a food bank. They pack boxes of fruit, vegetables and bread for families in need. Last year they packed more than 2,000 boxes. The project began five years ago with just six volunteers; today there are over forty.' How many volunteers did the project start with?","answer":"c","options":[{"key":"a","text":"five","diagnosis":"matched the wrong number — years, not volunteers"},{"key":"b","text":"forty","diagnosis":"took the current number instead of the starting number — time reference ignored"},{"key":"c","text":"six","diagnosis":"correct"},{"key":"d","text":"2,000","diagnosis":"matched the wrong quantity — boxes, not volunteers"}],"solution":"'The project began five years ago with just six volunteers.'","skill":"Locating a specific figure among several numbers in a text","misconceptions":["wrong-number-match","time-phrase-ignored"]},{"question_id":"Q-ENG-B1-RECEPTION-WRITTEN-L1-011","topic_id":"ENG-B1-RECEPTION-WRITTEN","level":1,"qtype":"mc","stem":"Read: 'Every Friday morning, students from a high school in Holon volunteer at a food bank. They pack boxes of fruit, vegetables and bread for families in need. Last year they packed more than 2,000 boxes. The project began five years ago with just six volunteers; today there are over forty.' What do the students do at the food bank?","answer":"d","options":[{"key":"a","text":"They cook meals for families.","diagnosis":"plausible food-bank activity not stated in the text — world knowledge replaced reading"},{"key":"b","text":"They collect money.","diagnosis":"invented detail — typical charity schema, not the text"},{"key":"c","text":"They deliver boxes to families.","diagnosis":"close to the text but changes the action — precision in reading not applied"},{"key":"d","text":"They pack boxes of food.","diagnosis":"correct"}],"solution":"The text says they pack boxes of fruit, vegetables and bread.","skill":"Distinguishing stated information from plausible schema-based guesses","misconceptions":["schema-over-text"]},{"question_id":"Q-ENG-B1-RECEPTION-WRITTEN-L2-010","topic_id":"ENG-B1-RECEPTION-WRITTEN","level":2,"qtype":"mc","stem":"Read: 'More and more parents drive their children to school, even when they live nearby. Experts say this is a mistake. Walking gives children exercise, teaches them independence, and reduces traffic around schools. Some cities have started walking-bus programs, in which groups of children walk together with an adult.' What is the main idea of the text?","answer":"c","options":[{"key":"a","text":"Parents should drive more carefully near schools.","diagnosis":"kept the topic (driving, schools) but reversed the message"},{"key":"b","text":"Cities should buy more school buses.","diagnosis":"misread 'walking bus' as a real bus — key term misunderstood"},{"key":"c","text":"Experts think more children should walk to school.","diagnosis":"correct"},{"key":"d","text":"Children who walk to school get better grades.","diagnosis":"invented benefit not stated in the text"}],"solution":"The text argues against driving children and lists the benefits of walking.","skill":"Identifying the main idea of an argumentative paragraph","misconceptions":["key-term-misread","message-reversal"]},{"question_id":"Q-ENG-B1-RECEPTION-WRITTEN-L2-011","topic_id":"ENG-B1-RECEPTION-WRITTEN","level":2,"qtype":"mc","stem":"Read: 'More and more parents drive their children to school, even when they live nearby. Experts say this is a mistake. Walking gives children exercise, teaches them independence, and reduces traffic around schools. Some cities have started walking-bus programs, in which groups of children walk together with an adult.' What is a 'walking bus'?","answer":"d","options":[{"key":"a","text":"A bus that stops close to children's homes.","diagnosis":"literal reading of 'bus' — the definition after 'in which' was not used"},{"key":"b","text":"A lesson that teaches children road safety.","diagnosis":"plausible program idea not in the text"},{"key":"c","text":"An exercise program in the school gym.","diagnosis":"linked to the 'exercise' benefit — wrong sentence used for the definition"},{"key":"d","text":"A group of children walking to school with an adult.","diagnosis":"correct"}],"solution":"The text defines it: groups of children walk together with an adult.","skill":"Using an in-text definition to understand a new term","misconceptions":["literal-reading","wrong-sentence-scan"]},{"question_id":"Q-ENG-B1-RECEPTION-WRITTEN-L2-012","topic_id":"ENG-B1-RECEPTION-WRITTEN","level":2,"qtype":"mc","stem":"Letter to the editor: 'Our town has a beautiful new sports hall, but teenagers who love skateboarding have nowhere to go. They skate in the shopping center, and everyone complains. A small skate park would solve the problem and give young people a safe place to meet. I hope the town council will act soon. — Noa, Grade 10.' Why did Noa write this letter?","answer":"a","options":[{"key":"a","text":"To persuade the town council to build a skate park.","diagnosis":"correct"},{"key":"b","text":"To invite readers to a skateboarding event.","diagnosis":"purpose invented — text type (opinion letter) not recognized"},{"key":"c","text":"To describe her favorite hobby.","diagnosis":"topic recognized but purpose missed — argument structure not identified"},{"key":"d","text":"To complain about the new sports hall.","diagnosis":"misread the contrast — the sports hall is mentioned positively"}],"solution":"Noa presents a problem and a solution and asks the council to act — a persuasive letter.","skill":"Identifying the writer's purpose","misconceptions":["purpose-vs-topic","contrast-misread"]},{"question_id":"Q-ENG-B1-RECEPTION-WRITTEN-L3-010","topic_id":"ENG-B1-RECEPTION-WRITTEN","level":3,"qtype":"mc","stem":"Letter to the editor: 'Our town has a beautiful new sports hall, but teenagers who love skateboarding have nowhere to go. They skate in the shopping center, and everyone complains. A small skate park would solve the problem and give young people a safe place to meet. I hope the town council will act soon. — Noa, Grade 10.' What is Noa's attitude toward the teenagers who skate in the shopping center?","answer":"c","options":[{"key":"a","text":"She wants them to stop skateboarding.","diagnosis":"solution misread — she proposes a place to skate, not stopping"},{"key":"b","text":"She thinks they should be punished.","diagnosis":"took the complainers' view for the writer's view — viewpoints confused"},{"key":"c","text":"She understands them but thinks they need a better place.","diagnosis":"correct"},{"key":"d","text":"She thinks skateboarding is too dangerous.","diagnosis":"safety mentioned ('safe place') but the attitude inferred is wrong"}],"solution":"Noa defends the teenagers ('have nowhere to go') and proposes a solution for them.","skill":"Inferring the writer's attitude","misconceptions":["viewpoint-confusion"]},{"question_id":"Q-ENG-B1-RECEPTION-WRITTEN-L3-011","topic_id":"ENG-B1-RECEPTION-WRITTEN","level":3,"qtype":"mc","stem":"Read: 'When Eli opened the envelope with his results, he read the letter twice. Then he called his mother, and she started to cry — but she was smiling at the same time. That evening, the whole family went out for a festive dinner.' What can we understand from the text?","answer":"d","options":[{"key":"a","text":"Eli failed his exams.","diagnosis":"interpreted crying literally — the smile and celebration ignored"},{"key":"b","text":"Eli's mother was angry with him.","diagnosis":"emotion misread — crying mapped to anger"},{"key":"c","text":"The family dinner was sad.","diagnosis":"'festive' not understood — inference built on the wrong emotion"},{"key":"d","text":"Eli received very good news.","diagnosis":"correct"}],"solution":"Tears of joy + smiling + festive dinner → the news was very good, though the text never says so directly.","skill":"Inferring meaning that is not stated directly","misconceptions":["literal-reading"]},{"question_id":"Q-ENG-B1-VOCAB-L1-010","topic_id":"ENG-B1-VOCAB","level":1,"qtype":"mc","stem":"Choose the correct answer: Hard work will ___ your chances of passing the exam.","answer":"c","options":[{"key":"a","text":"arrive","diagnosis":"sound-based guess — meaning not checked"},{"key":"b","text":"prove","diagnosis":"word-form confusion — prove/improve not distinguished"},{"key":"c","text":"improve","diagnosis":"correct"},{"key":"d","text":"approve","diagnosis":"similar-sounding word with a different meaning"}],"solution":"improve = make better: hard work improves your chances.","skill":"Mid-frequency verbs; distinguishing similar word forms","misconceptions":["word-form-confusion"]},{"question_id":"Q-ENG-B1-VOCAB-L1-011","topic_id":"ENG-B1-VOCAB","level":1,"qtype":"mc","stem":"Choose the correct answer: The scientists made an important ___ about the causes of the disease.","answer":"d","options":[{"key":"a","text":"discover","diagnosis":"verb used where a noun is needed — word-class error"},{"key":"b","text":"decision","diagnosis":"near-form noun with the wrong meaning — collocation 'make a decision' pulled the choice"},{"key":"c","text":"cover","diagnosis":"root-word confusion — morphology not analyzed"},{"key":"d","text":"discovery","diagnosis":"correct"}],"solution":"make a discovery = find something new: an important discovery.","skill":"Word families and word class (discover/discovery)","misconceptions":["word-class-error"]},{"question_id":"Q-ENG-B1-VOCAB-L2-010","topic_id":"ENG-B1-VOCAB","level":2,"qtype":"mc","stem":"___ the heavy rain, the football match continued.","answer":"c","options":[{"key":"a","text":"However","diagnosis":"sentence adverb used as a preposition — connector types confused"},{"key":"b","text":"Although","diagnosis":"contrast meaning right, grammar wrong — although needs a clause, not a noun phrase"},{"key":"c","text":"Despite","diagnosis":"correct"},{"key":"d","text":"Because of","diagnosis":"cause/contrast logic reversed"}],"solution":"Despite + noun phrase: Despite the heavy rain, the match continued.","skill":"Contrast connectors: despite vs. although vs. however","misconceptions":["connector-grammar","connector-logic"]},{"question_id":"Q-ENG-B1-VOCAB-L2-011","topic_id":"ENG-B1-VOCAB","level":2,"qtype":"mc","stem":"Choose the correct answer: The government plans to ___ taxes on sugary drinks from 10% to 15%.","answer":"d","options":[{"key":"a","text":"rise","diagnosis":"raise/rise confusion — rise is intransitive (things rise; people raise things)"},{"key":"b","text":"lift","diagnosis":"'lift a tax' means to remove it — direction of the change reversed"},{"key":"c","text":"grow","diagnosis":"intransitive verb used transitively — meaning close, grammar wrong"},{"key":"d","text":"raise","diagnosis":"correct"}],"solution":"raise (transitive) = make higher: raise taxes from 10% to 15%. rise has no object.","skill":"raise vs. rise and collocation with 'taxes'","misconceptions":["raise-rise-confusion"]},{"question_id":"Q-ENG-B1-VOCAB-L2-012","topic_id":"ENG-B1-VOCAB","level":2,"qtype":"mc","stem":"Choose the correct answer: Her ___ to detail makes her an excellent designer.","answer":"a","options":[{"key":"a","text":"attention","diagnosis":"correct"},{"key":"b","text":"intention","diagnosis":"similar-sounding noun with a different meaning"},{"key":"c","text":"attend","diagnosis":"verb used where a noun is needed — word-class error"},{"key":"d","text":"attentive","diagnosis":"adjective used where a noun is needed — word-class error"}],"solution":"The collocation is 'attention to detail'.","skill":"Word class and collocation (attention to detail)","misconceptions":["word-class-error","word-form-confusion"]},{"question_id":"Q-ENG-B1-VOCAB-L3-010","topic_id":"ENG-B1-VOCAB","level":3,"qtype":"mc","stem":"Choose the correct answer: Listening to very loud music can seriously ___ your hearing.","answer":"c","options":[{"key":"a","text":"waste","diagnosis":"'loss' meaning selected — losing something confused with harming it"},{"key":"b","text":"injure","diagnosis":"near-synonym that collocates with people and body parts, not with an ability like hearing"},{"key":"c","text":"damage","diagnosis":"correct"},{"key":"d","text":"break","diagnosis":"'break' generalized from objects that stop working to an ability"}],"solution":"You damage your hearing/health; you injure a person or a body part in an accident.","skill":"Near-synonym collocation (damage/injure/break)","misconceptions":["near-synonym-collocation"]},{"question_id":"Q-ENG-B1-VOCAB-L3-011","topic_id":"ENG-B1-VOCAB","level":3,"qtype":"mc","stem":"Choose the correct answer: Lack of sleep can badly ___ your memory and concentration.","answer":"d","options":[{"key":"a","text":"effect","diagnosis":"affect/effect confusion — effect is (almost always) a noun"},{"key":"b","text":"infect","diagnosis":"similar-sounding verb from the health field — form-based guess"},{"key":"c","text":"afford","diagnosis":"sound-based guess — meaning not checked"},{"key":"d","text":"affect","diagnosis":"correct"}],"solution":"affect (verb) = have an influence on: lack of sleep affects your memory.","skill":"affect vs. effect and similar forms","misconceptions":["affect-effect-confusion"]},{"question_id":"Q-ENG-B2-GRAMMAR-L1-010","topic_id":"ENG-B2-GRAMMAR","level":1,"qtype":"mc","stem":"Choose the correct answer: The results of the survey ___ next week.","answer":"d","options":[{"key":"a","text":"will publish","diagnosis":"active future used for a non-agent subject — passive not selected"},{"key":"b","text":"are publishing","diagnosis":"active progressive — the results cannot publish anything"},{"key":"c","text":"will published","diagnosis":"passive attempted but 'be' omitted — structure incomplete"},{"key":"d","text":"will be published","diagnosis":"correct"}],"solution":"The results receive the action: will + be + past participle — will be published.","skill":"Future passive","misconceptions":["active-for-passive","aux-omission"]},{"question_id":"Q-ENG-B2-GRAMMAR-L1-011","topic_id":"ENG-B2-GRAMMAR","level":1,"qtype":"mc","stem":"Choose the correct answer: This bridge ___ in 1932 and is still in use today.","answer":"a","options":[{"key":"a","text":"was built","diagnosis":"correct"},{"key":"b","text":"was building","diagnosis":"past progressive instead of passive — be+ing and be+participle confused"},{"key":"c","text":"has built","diagnosis":"perfect active — both voice and aspect wrong for a dated past event"},{"key":"d","text":"built","diagnosis":"active past for a non-agent subject — 'the bridge built' leaves the builder missing"}],"solution":"Past passive: was/were + past participle — The bridge was built in 1932.","skill":"Past simple passive","misconceptions":["active-for-passive"]},{"question_id":"Q-ENG-B2-GRAMMAR-L2-010","topic_id":"ENG-B2-GRAMMAR","level":2,"qtype":"mc","stem":"Choose the correct answer: 'I will call you tomorrow,' Dana said. → Dana said she ___ me the next day.","answer":"d","options":[{"key":"a","text":"will call","diagnosis":"no backshift — Hebrew reported speech keeps the original tense, classic interference"},{"key":"b","text":"called","diagnosis":"backshift overdone — future shifted to simple past instead of would"},{"key":"c","text":"would have called","diagnosis":"backshift overdone — perfect conditional used for a simple future"},{"key":"d","text":"would call","diagnosis":"correct"}],"solution":"In reported speech will → would: she said she would call me the next day.","skill":"Reported speech — tense backshift","misconceptions":["no-backshift-L1"]},{"question_id":"Q-ENG-B2-GRAMMAR-L2-011","topic_id":"ENG-B2-GRAMMAR","level":2,"qtype":"mc","stem":"He asked me where ___.","answer":"a","options":[{"key":"a","text":"I lived","diagnosis":"correct"},{"key":"b","text":"do I live","diagnosis":"question order kept AND no backshift"},{"key":"c","text":"I am living","diagnosis":"statement order achieved but backshift missing"},{"key":"d","text":"did I live","diagnosis":"question word order kept in the reported clause — very common interference"}],"solution":"Reported questions use statement word order + backshift: He asked me where I lived.","skill":"Reported questions — word order and backshift","misconceptions":["question-order-in-reported","no-backshift-L1"]},{"question_id":"Q-ENG-B2-GRAMMAR-L2-012","topic_id":"ENG-B2-GRAMMAR","level":2,"qtype":"mc","stem":"Choose the correct answer: The report ___ by the committee at the moment; it will be ready on Friday.","answer":"b","options":[{"key":"a","text":"has been reviewing","diagnosis":"perfect progressive active — voice and aspect both wrong"},{"key":"b","text":"is being reviewed","diagnosis":"correct"},{"key":"c","text":"is reviewing","diagnosis":"active progressive for a non-agent subject — passive progressive not formed"},{"key":"d","text":"is reviewed","diagnosis":"simple passive where 'at the moment' requires progressive — aspect dropped"}],"solution":"Present progressive passive: is/are + being + participle — The report is being reviewed now.","skill":"Present progressive passive","misconceptions":["active-for-passive","aspect-dropped"]},{"question_id":"Q-ENG-B2-GRAMMAR-L3-010","topic_id":"ENG-B2-GRAMMAR","level":3,"qtype":"mc","stem":"Choose the correct answer: If she ___ harder, she would have passed the exam.","answer":"d","options":[{"key":"a","text":"studied","diagnosis":"second-conditional form in a past unreal condition — conditional 2/3 confusion"},{"key":"b","text":"would have studied","diagnosis":"'would have' moved into the if-clause — condition and result confused"},{"key":"c","text":"has studied","diagnosis":"present perfect instead of past perfect — perfect forms not differentiated"},{"key":"d","text":"had studied","diagnosis":"correct"}],"solution":"Third conditional: if + past perfect, would have + participle — If she had studied harder, she would have passed.","skill":"Third conditional","misconceptions":["conditional-clause-mixing","perfect-forms-confusion"]},{"question_id":"Q-ENG-B2-GRAMMAR-L3-011","topic_id":"ENG-B2-GRAMMAR","level":3,"qtype":"mc","stem":"Choose the correct answer: ___ I known about the traffic, I would have left home earlier.","answer":"a","options":[{"key":"a","text":"Had","diagnosis":"correct"},{"key":"b","text":"Have","diagnosis":"present perfect auxiliary — inverted past perfect not formed"},{"key":"c","text":"Would","diagnosis":"result-clause auxiliary moved to the condition"},{"key":"d","text":"If","diagnosis":"'If I known' is incomplete — inversion pattern not recognized, auxiliary lost"}],"solution":"Formal inversion replaces 'if': Had I known = If I had known.","skill":"Inverted third conditional (formal register)","misconceptions":["inversion-not-recognized"]},{"question_id":"Q-ENG-B2-RECEPTION-WRITTEN-L1-010","topic_id":"ENG-B2-RECEPTION-WRITTEN","level":1,"qtype":"mc","stem":"Read: 'Remote work, once a rare privilege, has become standard practice in many industries. Supporters point to reduced commuting time and greater flexibility, while critics argue that creativity suffers when colleagues rarely meet face to face. A recent survey of 2,000 employees found that although most valued the freedom to work from home, nearly two-thirds admitted feeling less connected to their teams.' According to the survey, how did most employees feel about working from home?","answer":"d","options":[{"key":"a","text":"They felt more connected to their teams.","diagnosis":"reversed the survey finding — 'less connected' misread"},{"key":"b","text":"They felt it reduced their creativity.","diagnosis":"attributed the critics' claim to the surveyed employees — sources confused"},{"key":"c","text":"They wanted to stop working from home.","diagnosis":"conclusion invented — not supported by the text"},{"key":"d","text":"They valued the freedom it gave them.","diagnosis":"correct"}],"solution":"'most valued the freedom to work from home' — the concession clause carries the answer.","skill":"Extracting a specific finding from a dense informational text","misconceptions":["source-attribution","concession-misread"]},{"question_id":"Q-ENG-B2-RECEPTION-WRITTEN-L1-011","topic_id":"ENG-B2-RECEPTION-WRITTEN","level":1,"qtype":"mc","stem":"Read: 'Remote work, once a rare privilege, has become standard practice in many industries. Supporters point to reduced commuting time and greater flexibility, while critics argue that creativity suffers when colleagues rarely meet face to face. A recent survey of 2,000 employees found that although most valued the freedom to work from home, nearly two-thirds admitted feeling less connected to their teams.' What do critics of remote work argue?","answer":"a","options":[{"key":"a","text":"Creativity suffers when colleagues rarely meet in person.","diagnosis":"correct"},{"key":"b","text":"Two-thirds of employees feel disconnected.","diagnosis":"presented the survey finding as the critics' argument — sources confused"},{"key":"c","text":"Remote work should be completely banned.","diagnosis":"overstated the critics' position — claim strength not tracked"},{"key":"d","text":"Commuting wastes too much time.","diagnosis":"attributed the supporters' point to the critics — viewpoints confused"}],"solution":"'critics argue that creativity suffers when colleagues rarely meet face to face.'","skill":"Attributing claims to the correct source in a multi-voice text","misconceptions":["source-attribution","claim-overstatement"]},{"question_id":"Q-ENG-B2-RECEPTION-WRITTEN-L2-010","topic_id":"ENG-B2-RECEPTION-WRITTEN","level":2,"qtype":"mc","stem":"Read: 'The company's press release described the layoffs as an exciting opportunity to streamline our operations — a choice of words that few of the dismissed employees are likely to appreciate.' What does the writer suggest about the press release?","answer":"d","options":[{"key":"a","text":"It shows the employees were excited about the changes.","diagnosis":"took the company's euphemism at face value — irony missed"},{"key":"b","text":"It proves the company's operations improved.","diagnosis":"accepted the claim as fact — writer's distance from the source not noticed"},{"key":"c","text":"It promises the employees will be rehired.","diagnosis":"detail invented — not in the text"},{"key":"d","text":"Its positive language is inappropriate for such bad news.","diagnosis":"correct"}],"solution":"The comment 'few of the dismissed employees are likely to appreciate' signals criticism of the euphemistic wording.","skill":"Recognizing euphemism and the writer's critical distance","misconceptions":["irony-missed","claim-as-fact"]},{"question_id":"Q-ENG-B2-RECEPTION-WRITTEN-L2-011","topic_id":"ENG-B2-RECEPTION-WRITTEN","level":2,"qtype":"mc","stem":"Read: 'Bees are often praised for producing honey, yet their real economic value lies elsewhere. Roughly one-third of the food we eat depends on pollination, a service bees provide free of charge. If bee populations continue to decline, the price of everyday items such as apples and almonds could rise sharply.' What is the main point of the text?","answer":"a","options":[{"key":"a","text":"Bees matter to the economy mainly because of pollination, not honey.","diagnosis":"correct"},{"key":"b","text":"The rising price of apples and almonds is the text's main subject.","diagnosis":"turned the everyday-item example into the main point"},{"key":"c","text":"Bee populations are falling because food prices have risen sharply.","diagnosis":"reversed the text's causal direction — declining bees would cause the price rise, not the other way round"},{"key":"d","text":"Bees matter to the economy mainly because of the honey they produce.","diagnosis":"missed the contrast marked by 'yet' — honey kept as the source of the economic value"}],"solution":"'their real economic value lies elsewhere' + the pollination facts — the contrast marker 'yet' signals the main point.","skill":"Identifying the main point signaled by a contrast marker","misconceptions":["contrast-marker-missed","example-as-main-idea"]},{"question_id":"Q-ENG-B2-RECEPTION-WRITTEN-L2-012","topic_id":"ENG-B2-RECEPTION-WRITTEN","level":2,"qtype":"mc","stem":"Read: 'Bees are often praised for producing honey, yet their real economic value lies elsewhere. Roughly one-third of the food we eat depends on pollination, a service bees provide free of charge. If bee populations continue to decline, the price of everyday items such as apples and almonds could rise sharply.' According to the text, what could happen if bee populations keep falling?","answer":"b","options":[{"key":"a","text":"Farmers would start paying bees for pollination.","diagnosis":"misread 'free of charge' — literal recombination of details"},{"key":"b","text":"The price of some everyday foods could rise sharply.","diagnosis":"correct"},{"key":"c","text":"Honey would disappear from stores.","diagnosis":"predicted from the honey detail — the stated consequence not located"},{"key":"d","text":"People would stop eating apples and almonds.","diagnosis":"overstated the consequence — 'price could rise' turned into disappearance"}],"solution":"'the price of everyday items such as apples and almonds could rise sharply.'","skill":"Locating a stated consequence in a conditional sentence","misconceptions":["claim-overstatement","detail-recombination"]},{"question_id":"Q-ENG-B2-RECEPTION-WRITTEN-L3-010","topic_id":"ENG-B2-RECEPTION-WRITTEN","level":3,"qtype":"mc","stem":"Read: 'Another revolutionary fitness gadget has arrived in stores, promising to transform your health while you sit comfortably on the sofa. Its makers claim that ten minutes a day will replace a full workout. History suggests such promises rarely survive contact with reality.' What is the writer's attitude toward the new gadget?","answer":"d","options":[{"key":"a","text":"Enthusiastic","diagnosis":"read the ironic 'revolutionary' as the writer's own praise"},{"key":"b","text":"Neutral","diagnosis":"treated the text as a plain report and overlooked the evaluative last sentence"},{"key":"c","text":"Worried","diagnosis":"negative tone detected but of the wrong kind — doubt misread as fear of danger"},{"key":"d","text":"Skeptical","diagnosis":"correct — 'History suggests such promises rarely survive contact with reality' marks doubt"}],"solution":"'History suggests such promises rarely survive contact with reality' + ironic 'revolutionary' → skepticism.","skill":"Detecting irony and the writer's stance","misconceptions":["irony-missed","stance-vs-report"]},{"question_id":"Q-ENG-B2-RECEPTION-WRITTEN-L3-011","topic_id":"ENG-B2-RECEPTION-WRITTEN","level":3,"qtype":"mc","stem":"Read: 'The recommendation letter noted only that the student was always punctual and neatly dressed. The admissions officer read it twice, sighed, and placed the application on the smaller of the two piles.' What can we infer from the text?","answer":"a","options":[{"key":"a","text":"The letter's faint praise hurt the student's chances.","diagnosis":"correct"},{"key":"b","text":"The letter praised the student's academic ability.","diagnosis":"contradicts 'noted only' — implicit omission not noticed"},{"key":"c","text":"The smaller pile was for the best applications.","diagnosis":"possible in isolation but clashes with the sigh and the empty praise — cues not integrated"},{"key":"d","text":"The officer was impressed by the student's punctuality.","diagnosis":"surface-positive words taken at face value — the implication of 'only' missed"}],"solution":"Praising only punctuality and dress implies nothing stronger could be said; the sigh and the smaller pile suggest rejection.","skill":"Integrating implicit cues to infer unstated meaning","misconceptions":["faint-praise-missed","cue-integration"]},{"question_id":"Q-ENG-B2-VOCAB-L1-010","topic_id":"ENG-B2-VOCAB","level":1,"qtype":"mc","stem":"Choose the correct answer: The two studies produced remarkably ___ results, so the researchers were confident in their conclusions.","answer":"d","options":[{"key":"a","text":"same","diagnosis":"'same' needs 'the' and does not fit after 'remarkably' — form and usage confused"},{"key":"b","text":"familiar","diagnosis":"similar/familiar sound-alike confusion"},{"key":"c","text":"opposite","diagnosis":"logic of the sentence ignored — confidence requires agreement between studies"},{"key":"d","text":"similar","diagnosis":"correct"}],"solution":"Two studies agreeing = similar results; that is why the researchers were confident.","skill":"Academic adjectives and sentence logic","misconceptions":["similar-familiar-confusion","same-without-the"]},{"question_id":"Q-ENG-B2-VOCAB-L1-011","topic_id":"ENG-B2-VOCAB","level":1,"qtype":"mc","stem":"Choose the correct answer: Doctors are concerned about the sharp ___ in childhood obesity over the last decade.","answer":"a","options":[{"key":"a","text":"increase","diagnosis":"correct"},{"key":"b","text":"growing","diagnosis":"-ing form used where a noun is needed — word-class error"},{"key":"c","text":"addition","diagnosis":"near-meaning noun with the wrong collocation"},{"key":"d","text":"raise","diagnosis":"raise as a noun means a pay raise — raise/rise/increase not differentiated"}],"solution":"The collocation is 'an increase in X': a sharp increase in childhood obesity.","skill":"Academic nouns of change and their collocations","misconceptions":["word-class-error","raise-rise-confusion"]},{"question_id":"Q-ENG-B2-VOCAB-L2-010","topic_id":"ENG-B2-VOCAB","level":2,"qtype":"mc","stem":"Choose the correct answer: The report ___ that air pollution is the main cause of the problem.","answer":"d","options":[{"key":"a","text":"decides","diagnosis":"human-agent verb given to a document — reporting-verb register not acquired"},{"key":"b","text":"invents","diagnosis":"meaning error — negative verb changes the claim's status"},{"key":"c","text":"results","diagnosis":"word-class/pattern error — 'results that' is not an English pattern"},{"key":"d","text":"concludes","diagnosis":"correct"}],"solution":"Documents conclude/show/state: The report concludes that...","skill":"Academic reporting verbs","misconceptions":["reporting-verb-register"]},{"question_id":"Q-ENG-B2-VOCAB-L2-011","topic_id":"ENG-B2-VOCAB","level":2,"qtype":"mc","stem":"Choose the correct answer: She was ___ to accept the job offer because the salary was so low.","answer":"a","options":[{"key":"a","text":"reluctant","diagnosis":"correct"},{"key":"b","text":"refused","diagnosis":"meaning close but the pattern 'was refused to accept' is impossible — word class and structure confused"},{"key":"c","text":"delighted","diagnosis":"logic reversed — low salary does not cause delight"},{"key":"d","text":"relevant","diagnosis":"sound-alike confusion — reluctant/relevant"}],"solution":"reluctant to do something = not wanting to do it: reluctant to accept because the salary was low.","skill":"Mid-frequency adjectives of attitude","misconceptions":["sound-alike-confusion","logic-check-skipped"]},{"question_id":"Q-ENG-B2-VOCAB-L2-012","topic_id":"ENG-B2-VOCAB","level":2,"qtype":"mc","stem":"Choose the correct answer: Before making a decision, you should take all the costs into ___.","answer":"b","options":[{"key":"a","text":"thought","diagnosis":"meaning-based guess — fixed expression not retrieved"},{"key":"b","text":"account","diagnosis":"correct"},{"key":"c","text":"attention","diagnosis":"blend with 'pay attention to' — collocations mixed"},{"key":"d","text":"mind","diagnosis":"blend with 'bear in mind' — collocations mixed"}],"solution":"The fixed expression is 'take (something) into account'.","skill":"Fixed academic expressions","misconceptions":["collocation-blending"]},{"question_id":"Q-ENG-B2-VOCAB-L3-010","topic_id":"ENG-B2-VOCAB","level":3,"qtype":"mc","stem":"Read: 'The new manager's ideas didn't go down well with the staff.' What does this sentence mean?","answer":"d","options":[{"key":"a","text":"The ideas were not written down.","diagnosis":"literal reading of 'go down' — idiom not recognized"},{"key":"b","text":"The staff did not understand the ideas.","diagnosis":"partial interpretation — dislike read as confusion"},{"key":"c","text":"The manager canceled his ideas.","diagnosis":"agent confusion — the staff's reaction attributed to the manager"},{"key":"d","text":"The staff did not like the manager's ideas.","diagnosis":"correct"}],"solution":"'go down well/badly with someone' = be received well/badly: the staff did not like the ideas.","skill":"Understanding idiomatic expressions in context","misconceptions":["literal-idiom-reading"]},{"question_id":"Q-ENG-B2-VOCAB-L3-011","topic_id":"ENG-B2-VOCAB","level":3,"qtype":"mc","stem":"The politician's answer was deliberately ___, so nobody knew what he really planned to do.","answer":"a","options":[{"key":"a","text":"vague","diagnosis":"correct"},{"key":"b","text":"vogue","diagnosis":"sound-alike confusion — vague/vogue"},{"key":"c","text":"accurate","diagnosis":"logic reversed — precision would reveal the plans"},{"key":"d","text":"clear","diagnosis":"logic reversed — a clear answer would reveal his plans"}],"solution":"vague = unclear, without details: a deliberately vague answer hides one's plans.","skill":"Precise mid-frequency adjectives; checking sentence logic","misconceptions":["sound-alike-confusion","logic-check-skipped"]},{"question_id":"Q-ENG-PreA1-LITERACY-L1-010","topic_id":"ENG-PreA1-LITERACY","level":1,"qtype":"mc","stem":"מהי האות הקטנה של D?","answer":"c","options":[{"key":"a","text":"q","diagnosis":"mirror + rotation confusion — letter forms not yet distinguished"},{"key":"b","text":"b","diagnosis":"b/d mirror-image confusion — very common at beginning literacy"},{"key":"c","text":"d","diagnosis":"correct"},{"key":"d","text":"p","diagnosis":"rotation confusion (d/p) — letter orientation not yet stable"}],"solution":"The capital letter D matches the small letter d.","skill":"Matching capital and lowercase letter forms","misconceptions":["letter-mirror-confusion"],"area":"E-LIT","area_he":"אותיות וצלילים","tier":"core"},{"question_id":"Q-ENG-PreA1-LITERACY-L1-011","topic_id":"ENG-PreA1-LITERACY","level":1,"qtype":"mc","stem":"איזו מילה מתחילה בצליל /m/?","answer":"d","options":[{"key":"a","text":"name","diagnosis":"heard /m/ inside the word, not at the start — initial-sound isolation not yet stable"},{"key":"b","text":"nose","diagnosis":"/m/–/n/ nasal confusion — similar sounds not yet distinguished"},{"key":"c","text":"lamp","diagnosis":"heard /m/ at the end of the word — position of sound not attended to"},{"key":"d","text":"man","diagnosis":"correct"}],"solution":"man begins with the sound /m/.","skill":"Phonemic awareness: identifying the initial sound of a word","misconceptions":["initial-sound-isolation"],"area":"E-LIT","area_he":"אותיות וצלילים","tier":"core"},{"question_id":"Q-ENG-PreA1-LITERACY-L2-010","topic_id":"ENG-PreA1-LITERACY","level":2,"qtype":"mc","stem":"איזו מילה מתחרזת עם cat?","answer":"c","options":[{"key":"a","text":"car","diagnosis":"matched the beginning (ca-) only — rhyme concept not yet stable"},{"key":"b","text":"cap","diagnosis":"matched the beginning sounds (ca-) instead of the rime (-at)"},{"key":"c","text":"hat","diagnosis":"correct"},{"key":"d","text":"cut","diagnosis":"matched first and last letters but changed the vowel — rime not attended to"}],"solution":"cat and hat share the ending -at, so they rhyme.","skill":"Phonemic awareness: recognizing rhyming words","misconceptions":["onset-vs-rime"],"area":"E-LIT","area_he":"אותיות וצלילים","tier":"core"},{"question_id":"Q-ENG-PreA1-LITERACY-L2-011","topic_id":"ENG-PreA1-LITERACY","level":2,"qtype":"mc","stem":"איזו אות נותנת את הצליל האחרון במילה dog?","answer":"d","options":[{"key":"a","text":"j","diagnosis":"letter-NAME confusion: the name of g sounds like /dʒ/ — letter name vs. letter sound not separated"},{"key":"b","text":"d","diagnosis":"gave the first sound instead of the last — sound position not attended to"},{"key":"c","text":"k","diagnosis":"/g/–/k/ voiced/voiceless confusion"},{"key":"d","text":"g","diagnosis":"correct"}],"solution":"dog ends with the sound /g/, written with the letter g.","skill":"Letter-sound correspondence: final sounds","misconceptions":["letter-name-vs-sound"],"area":"E-LIT","area_he":"אותיות וצלילים","tier":"core"},{"question_id":"Q-ENG-PreA1-LITERACY-L3-010","topic_id":"ENG-PreA1-LITERACY","level":3,"qtype":"mc","stem":"כמה צלילים שומעים במילה fish?","answer":"c","options":[{"key":"a","text":"5","diagnosis":"over-segmentation — phoneme counting not yet stable"},{"key":"b","text":"4","diagnosis":"counted letters instead of sounds — 'sh' is two letters but one sound"},{"key":"c","text":"3","diagnosis":"correct — /f/ /i/ /sh/"},{"key":"d","text":"2","diagnosis":"blended the vowel with a consonant — incomplete segmentation"}],"solution":"fish = /f/ + /i/ + /sh/ — three sounds (sh is one sound written with two letters).","skill":"Phonemic awareness: counting phonemes in a word","misconceptions":["letters-equal-sounds"],"area":"E-LIT","area_he":"אותיות וצלילים","tier":"core"},{"question_id":"Q-ENG-PreA1-LITERACY-L3-011","topic_id":"ENG-PreA1-LITERACY","level":3,"qtype":"mc","stem":"חברו את הצלילים s - t - o - p. איזו מילה יוצאת?","answer":"d","options":[{"key":"a","text":"spot","diagnosis":"blended the sounds in the wrong order — sequencing error"},{"key":"b","text":"tops","diagnosis":"moved the first sound to the end — sequencing error"},{"key":"c","text":"pot","diagnosis":"dropped the first sound of the cluster st- — consonant clusters are hard for Hebrew speakers"},{"key":"d","text":"stop","diagnosis":"correct"}],"solution":"Blending s+t+o+p in order gives the word stop.","skill":"Decoding: blending sounds into a word (initial consonant cluster)","misconceptions":["sound-sequencing","cluster-reduction"],"area":"E-LIT","area_he":"אותיות וצלילים","tier":"core"},{"question_id":"Q-ENG-PreA1-RECEPTION-WRITTEN-L1-010","topic_id":"ENG-PreA1-RECEPTION-WRITTEN","level":1,"qtype":"mc","stem":"איזו מילה באנגלית פירושה «כֶּלֶב»?","answer":"a","options":[{"key":"a","text":"dog","diagnosis":"correct"},{"key":"b","text":"bog","diagnosis":"b/d mirror confusion at word level"},{"key":"c","text":"dug","diagnosis":"read the first and last letters only — medial vowel not checked"},{"key":"d","text":"god","diagnosis":"reversed letter order — possible influence of right-to-left reading in Hebrew"}],"solution":"המילה dog נכתבת d-o-g. שאר האפשרויות נבדלות ממנה באות אחת בלבד.","skill":"זיהוי הצורה הכתובה של מילה מוכרת בעל-פה, בין מילים דומות חזותית","misconceptions":["letter-mirror-confusion","reading-direction"],"area":"E-LIT","area_he":"אותיות וצלילים","tier":"core"},{"question_id":"Q-ENG-PreA1-RECEPTION-WRITTEN-L1-011","topic_id":"ENG-PreA1-RECEPTION-WRITTEN","level":1,"qtype":"mc","stem":"איזו מילה באנגלית פירושה «אִמָּא»?","answer":"b","options":[{"key":"a","text":"wow","diagnosis":"m/w mirror (flip) confusion"},{"key":"b","text":"mom","diagnosis":"correct"},{"key":"c","text":"mam","diagnosis":"middle vowel not checked — partial decoding"},{"key":"d","text":"mon","diagnosis":"m/n visual confusion at the end of the word"}],"solution":"המילה mom נכתבת m-o-m. שאר האפשרויות נבדלות ממנה באות אחת בלבד.","skill":"זיהוי הצורה הכתובה של מילה מוכרת בעל-פה, בין מילים דומות חזותית","misconceptions":["partial-decoding"],"area":"E-LIT","area_he":"אותיות וצלילים","tier":"core"},{"question_id":"Q-ENG-PreA1-RECEPTION-WRITTEN-L2-010","topic_id":"ENG-PreA1-RECEPTION-WRITTEN","level":2,"qtype":"mc","stem":"איזו מילה היא צבע?","answer":"a","options":[{"key":"a","text":"red","diagnosis":"correct"},{"key":"b","text":"bed","diagnosis":"decoded by rhyme/shape similarity to red — meaning not retrieved"},{"key":"c","text":"ran","diagnosis":"matched the first letter only — guessing from initial letter"},{"key":"d","text":"ten","diagnosis":"recognized a familiar sight word but not its meaning category"}],"solution":"red is a color; bed, ran and ten are not.","skill":"Reading a high-frequency word and linking it to its meaning","misconceptions":["first-letter-guessing"],"area":"E-REA","area_he":"הבנת הנקרא","tier":"core"},{"question_id":"Q-ENG-PreA1-RECEPTION-WRITTEN-L2-011","topic_id":"ENG-PreA1-RECEPTION-WRITTEN","level":2,"qtype":"mc","stem":"איזו מילה היא מספר?","answer":"b","options":[{"key":"a","text":"socks","diagnosis":"similar sounds — decoding by first sound only"},{"key":"b","text":"six","diagnosis":"correct"},{"key":"c","text":"mix","diagnosis":"rhymes with six — chose by sound, not meaning"},{"key":"d","text":"sit","diagnosis":"visually similar word (si-) — final letter not checked"}],"solution":"six is a number; sit, socks and mix are not.","skill":"Reading high-frequency words and identifying meaning (numbers)","misconceptions":["partial-decoding"],"area":"E-REA","area_he":"הבנת הנקרא","tier":"core"},{"question_id":"Q-ENG-PreA1-RECEPTION-WRITTEN-L3-010","topic_id":"ENG-PreA1-RECEPTION-WRITTEN","level":3,"qtype":"mc","stem":"לפי המשפט The cat is big — מי גדול?","answer":"a","options":[{"key":"a","text":"the cat","diagnosis":"correct"},{"key":"b","text":"the hat","diagnosis":"cat/hat visual-rhyme confusion — decoding error"},{"key":"c","text":"the dog","diagnosis":"guessed a familiar word that is not in the sentence — did not read the text"},{"key":"d","text":"the boy","diagnosis":"guessed without reading — sentence not decoded"}],"solution":"The sentence says the cat is big.","skill":"Reading a very short sentence of sight words and understanding it","misconceptions":["guessing-not-reading"],"area":"E-REA","area_he":"הבנת הנקרא","tier":"core"},{"question_id":"Q-ENG-PreA1-RECEPTION-WRITTEN-L3-011","topic_id":"ENG-PreA1-RECEPTION-WRITTEN","level":3,"qtype":"mc","stem":"לפי המשפט I like milk — מה אני אוהב?","answer":"b","options":[{"key":"a","text":"water","diagnosis":"guessed a familiar drink instead of reading the word"},{"key":"b","text":"milk","diagnosis":"correct"},{"key":"c","text":"like","diagnosis":"picked a word from the sentence but not the one the question asks about"},{"key":"d","text":"milek","diagnosis":"chose a non-word that looks similar — letter-by-letter checking not applied"}],"solution":"The sentence says: I like milk.","skill":"Reading a short sentence and picking out the key word","misconceptions":["guessing-not-reading"],"area":"E-REA","area_he":"הבנת הנקרא","tier":"core"},{"question_id":"Q-ENG-PreA1-VOCAB-L1-010","topic_id":"ENG-PreA1-VOCAB","level":1,"qtype":"mc","stem":"איזו מילה היא בעל חיים?","answer":"a","options":[{"key":"a","text":"cat","diagnosis":"correct"},{"key":"b","text":"hat","diagnosis":"rhymes with cat — chose by sound, meaning not retrieved"},{"key":"c","text":"car","diagnosis":"looks and sounds like cat — form confusion"},{"key":"d","text":"ten","diagnosis":"familiar word, wrong category — meaning not retrieved"}],"solution":"A cat is an animal.","skill":"Recognizing the meaning of high-frequency words (animals)","misconceptions":["form-over-meaning"],"area":"E-VOC","area_he":"אוצר מילים","tier":"core"},{"question_id":"Q-ENG-PreA1-VOCAB-L1-011","topic_id":"ENG-PreA1-VOCAB","level":1,"qtype":"mc","stem":"איזו מילה היא צבע?","answer":"b","options":[{"key":"a","text":"two","diagnosis":"number/color category confusion — both learned as early word sets"},{"key":"b","text":"blue","diagnosis":"correct"},{"key":"c","text":"shoe","diagnosis":"rhymes with blue — chose by sound"},{"key":"d","text":"ball","diagnosis":"begins with the same letter — chose by form, not meaning"}],"solution":"blue is a color.","skill":"Recognizing the meaning of high-frequency words (colors)","misconceptions":["form-over-meaning"],"area":"E-VOC","area_he":"אוצר מילים","tier":"core"},{"question_id":"Q-ENG-PreA1-VOCAB-L2-010","topic_id":"ENG-PreA1-VOCAB","level":2,"qtype":"mc","stem":"פוגשים חבר בבוקר. מה אומרים?","answer":"a","options":[{"key":"a","text":"Good morning!","diagnosis":"correct"},{"key":"b","text":"Good night!","diagnosis":"chose the opposite formulaic chunk — chunks learned as a pair but not yet mapped to situations"},{"key":"c","text":"Thank you!","diagnosis":"familiar chunk used in the wrong situation"},{"key":"d","text":"Goodbye!","diagnosis":"greeting/parting confusion"}],"solution":"In the morning we say: Good morning!","skill":"Using formulaic chunks in the right routine situation","misconceptions":["chunk-situation-mapping"],"area":"E-VOC","area_he":"אוצר מילים","tier":"core"},{"question_id":"Q-ENG-PreA1-VOCAB-L2-011","topic_id":"ENG-PreA1-VOCAB","level":2,"qtype":"mc","stem":"השלימו: Big is the opposite of ___","answer":"b","options":[{"key":"a","text":"hot","diagnosis":"chose another opposite-pair word from a different pair (hot/cold)"},{"key":"b","text":"small","diagnosis":"correct"},{"key":"c","text":"happy","diagnosis":"familiar adjective, wrong pair — opposites not yet mapped"},{"key":"d","text":"tall","diagnosis":"size-word confusion — tall is also about size but not the opposite of big"}],"solution":"The opposite of big is small.","skill":"Knowing basic opposite pairs","misconceptions":["opposite-pairs"],"area":"E-VOC","area_he":"אוצר מילים","tier":"core"},{"question_id":"Q-ENG-PreA1-VOCAB-L3-011","topic_id":"ENG-PreA1-VOCAB","level":3,"qtype":"mc","stem":"איזה מספר בא אחרי seven?","answer":"b","options":[{"key":"a","text":"seven","diagnosis":"repeated the number in the question — question not understood"},{"key":"b","text":"eight","diagnosis":"correct"},{"key":"c","text":"ten","diagnosis":"number words known but sequence not stable"},{"key":"d","text":"six","diagnosis":"gave the number BEFORE seven — after/before confusion"}],"solution":"...six, seven, eight — eight comes after seven.","skill":"Number words in sequence; understanding 'after'","misconceptions":["before-after-confusion"],"area":"E-VOC","area_he":"אוצר מילים","tier":"core"}]};
